// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

contract Crowdfunding {

    struct Campaign {
        address creator;
        uint goal;
        uint deadline;
        uint amountRaised;
    }
    
    mapping(uint => Campaign) public campaigns;
    mapping(uint => mapping(address => uint)) public contributions;
    uint public campaignCount;
    
    // Events for gas-efficient indexing
    event CampaignCreated(uint indexed campaignId, address indexed creator, uint goal, uint deadline);
    event Contributed(uint indexed campaignId, address indexed contributor, uint amount);

    function createCampaign(uint _goal, uint _duration) public {
        campaignCount++;
        uint deadline = block.timestamp + _duration;
        campaigns[campaignCount] = Campaign(
            msg.sender,
            _goal,
            deadline,
            0
        );
        emit CampaignCreated(campaignCount, msg.sender, _goal, deadline);
    }

    function contribute(uint _id) public payable {
        Campaign storage c = campaigns[_id];
        require(c.creator != address(0), "Campaign not found");
        require(block.timestamp < c.deadline, "Deadline passed");
        require(msg.value > 0, "Contribution must be > 0");

        c.amountRaised += msg.value;
        contributions[_id][msg.sender] += msg.value;
        
        emit Contributed(_id, msg.sender, msg.value);
    }

    function isContributor(uint _id, address _user) external view returns (bool) {
        return contributions[_id][_user] > 0;
    }
}
